const T=window.TOOLS,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],WORK_KEY='pina-fieldguide-work-v1',META_KEY='pina-fieldguide-meta-v1',TRAIL_KEY='pina-fieldguide-trail-v2';
