let storageOK=true;function read(k,f){try{return JSON.parse(localStorage.getItem(k)||'null')||f}catch(e){storageOK=false;return f}}
let work=read(WORK_KEY,{}),meta={pins:[],project:'My working project',last:1,displayName:'Aarshi',studioProgress:{},...read(META_KEY,{})},trail={passed:[],answers:{},maps:{},...read(TRAIL_KEY,{})};if(!Array.isArray(meta.pins))meta.pins=[];meta.pins=meta.pins.filter(n=>Number.isInteger(n)&&n>=0&&n<7);if(!meta.studioProgress||typeof meta.studioProgress!=='object')meta.studioProgress={};if(!Array.isArray(work.ledger))work.ledger=[['','','','','','']];if(!Array.isArray(trail.passed))trail.passed=[];
let zoomedMaps={},mapPart={},reviewMove=0,liveMood='curious';function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch(e){storageOK=false;return false}}function saveWork(){if(!persist(WORK_KEY,work))toast('This browser cannot save entries. Keep a backup of your work.');updateDraft();updateWorkingVisual()}function saveMeta(){persist(META_KEY,meta)}function saveTrail(){persist(TRAIL_KEY,trail)}
function ic(n){const p={arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1v15"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6Zm6-3v15m6-12v15"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',check:'<path d="m4 12 5 5L20 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',star:'<path d="m12 3 2.6 5.8L21 10l-4.6 4.4.9 6.6-5.3-3.3L6.7 21l.9-6.6L3 10l6.4-1.2Z"/>',plus:'<path d="M12 4v16M4 12h16"/>',pen:'<path d="m4 16 12-12 4 4L8 20H4v-4Zm9-9 4 4"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>'};return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${p[n]||p.arrow}</svg>`}
