function art(id,variant=0){let shape='';const label=(x,y,s,z=12)=>`<text x="${x}" y="${y}" font-size="${z}" text-anchor="middle" fill="#343c37" font-family="sans-serif">${s}</text>`;if(id===1)shape='<path d="m204 25 58 94h-119z" fill="#e5f4eb" stroke="#3b5044" stroke-width="2"/><path d="m143 119 119 0-24 119-44 33-39-65z" fill="#aed1bd" stroke="#3b5044" stroke-width="2"/><path d="m204 25-16 94-45 0z" fill="#f4faf6"/><path d="m188 119 74 0-68 152z" fill="#cfeada"/><path d="M83 120q32-10 64 0t64 0 64 0 64 0" fill="none" stroke="#739180" stroke-width="2"/>'+label(207,301,'LOOK BELOW THE WORDS',10);else if(id===2)shape='<g transform="rotate(-7 150 130)"><rect x="73" y="40" width="125" height="112" rx="2" fill="#fffdf5" stroke="#2b352f" stroke-width="2"/>'+label(135,89,'SPEED')+label(135,118,'one frame',10)+'</g><g transform="rotate(5 265 208)"><rect x="201" y="150" width="143" height="113" rx="2" fill="#e8f5ed" stroke="#2b352f" stroke-width="2"/>'+label(272,201,'CONFIDENCE')+label(272,229,'a fair rival',10)+'</g>';else if(id===3)shape='<path d="M134 49v223m116-223v223M134 77h116m-116 55h116m-116 55h116m-116 55h116" fill="none" stroke="#44534a" stroke-width="4" stroke-linecap="round"/><circle cx="190" cy="63" r="16" fill="#77bc94" stroke="#2f3933" stroke-width="2"/>'+label(190,68,'F1',11).replace('#343c37','#fff');else if(id===4)shape='<path d="M62 171q50-80 96 0t96 0 96 0" stroke="#679078" fill="none" stroke-width="3"/>'+[62,134,206,278,350].map((x,i)=>`<circle cx="${x}" cy="171" r="12" fill="${i===2&&variant===1?'#faf6ec':'#c6e6d3'}" stroke="#333c37" stroke-width="2"/>`).join('')+label(206,84,'ONE REASON')+label(206,258,'CARRIED THROUGH',10);else if(id===5)shape='<circle cx="208" cy="160" r="106" fill="none" stroke="#6c8878" stroke-width="2" stroke-dasharray="5 7"/>'+[0,1,2,3,4].map((i)=>{const a=(-90+i*72)*Math.PI/180;return `<circle cx="${208+106*Math.cos(a)}" cy="${160+106*Math.sin(a)}" r="13" fill="#dff0e6" stroke="#36433b" stroke-width="2"/>`}).join('')+label(208,154,'EVERY REVIEW')+label(208,178,'IS A LESSON',11);else if(id===6)shape='<g transform="rotate(-7 210 160)"><path d="M82 70h245v181H82z" fill="#ebf6f0" stroke="#2e3a33" stroke-width="2"/><path d="M82 115h245M145 70v181" stroke="#2e3a33" stroke-width="2"/>'+label(209,99,'THE VALUE OF THINKING',10)+label(234,162,'a decision')+label(234,198,'worth making',14)+'</g>';else shape='<g transform="rotate(-8 200 160)"><path d="M64 65h274v142H139l-42 35 8-35H64z" fill="#fffef9" stroke="#303934" stroke-width="2"/>'+label(201,117,'What I meant…',18)+label(201,159,'What you read.',18)+'</g>';return `<svg class="chapter-art" viewBox="0 0 420 325" aria-hidden="true">${shape}</svg>`}
function header(){return `<header class="studio-header"><a href="#home" class="wordmark" aria-label="PINA home">PINA<span>STORY STUDIO</span></a><button class="chapters-button" aria-label="All tools" data-action="chapters">All tools <span>↗</span></button><a href="#notebook" class="notebook-button" aria-label="My notebook">${ic('book')}<span>My notebook</span></a></header>`}
function shell(body,cls=''){return `${header()}<main id="main" tabindex="-1" class="${cls}">${body}</main><footer class="studio-footer"><span>AARSHI JAIN · PINA TOOLKIT</span><button data-action="shelf">The research shelf ↗</button></footer>`}
function trailNav(id,active='choose'){return `<nav class="story-trail" aria-label="Chapter navigation"><a href="#door/${id}" class="${active==='choose'?'active':''}">01 <span>Choose</span></a><i></i><a href="#story/${id}" class="${active==='story'?'active':''}">02 <span>The comic</span></a><i></i><a href="#make/${id}/context" class="${active==='make'?'active':''}">03 <span>Your turn</span></a><i></i><a href="#make/${id}/output" class="${active==='output'?'active':''}">04 <span>Your draft</span></a></nav>`}
const TOOL_GROUPS=[
 ['Briefs & stakeholders',[1,7,14]],
 ['Analysis & decisions',[2,3,11,9,13]],
 ['Messages & persuasion',[0,10,8]],
 ['Pitches & value',[12,6]],
 ['Review & handover',[4,5]]
];

function toolDirectory(menu=false){
 return TOOL_GROUPS.map(([title,ids])=>`<section class="tool-group"><h${menu?3:2}>${title}</h${menu?3:2}>
  <div class="${menu?'chapter-menu':'dialogue-choices tool-directory-cards'}">${ids.map(id=>{
   const t=ANYTIME[id]||T[id], href=ANYTIME[id]?anyUrl(id):`#door/${id}`;
   return `<a ${menu?'data-close="chapter-dialog"':`class="reply" data-pip-directory="${id}"`} href="${href}">
    <div><b>${esc(t.name)}</b><span class="directory-arrow" aria-hidden="true">→</span>${menu?'':'<small data-pip-badge></small>'}</div>${directoryArt(id)}</a>`;
  }).join('')}</div></section>`).join('');
}

function home(){
 return shell(`<section class="welcome-spread directory-welcome">
  <div class="welcome-copy"><p class="scribble welcome-note">Hey ${esc(meta.displayName||'Aarshi')}. Welcome back.</p><h1>What are we<br>working through<span class="blue"> today?</span></h1><p class="directory-intro">Pick a tool for the work in front of you.</p></div>
  <aside class="welcome-character"><div class="speech welcome-speech"><span class="speaker-tag">PIP SAYS</span><h2>Start where the work gets stuck.</h2><p>Bring the brief, the message or the decision you’re working on. I’ll walk you through it.</p></div>${guide('curious')}</aside>
 </section><div class="pip-directory-status" data-pip-show-all hidden><span>Pip highlighted a route for your material.</span><button class="text-link" type="button">Show all tools</button></div><section id="tool-directory" class="tool-directory" aria-label="All tools">${toolDirectory()}</section>
 <section class="tool-connections" aria-labelledby="connections-title"><h2 id="connections-title">How the tools connect</h2>
  <p>Different people can read the same brief, argument or message in different ways. Use the tools together to make those readings visible and decide what to change.</p>
  <ol>
   <li><b>Get oriented.</b> Use Brief X-Ray to clarify the request, Stakeholder Lens to see who can shape the outcome, and Empathy Lens to understand one person’s perspective.</li>
   <li><b>Build a case.</b> Use Frame Test to compare explanations, Evidence Ladder to weigh support, and Logic Trap Deck to check the reasoning. In a negotiation, use Deal Table to plan trades and 3E Scale to compare priorities.</li>
   <li><b>Make it land.</b> Use Reading Check and Trust Triangle to see how a message will be heard. Use Lever Board to check the ask, then Pitch Arc or Value Case to make the case.</li>
   <li><b>Carry the decision forward.</b> Use Thread Check to see what changed and Reasoned Review to record why.</li>
  </ol>${thinkingCoverage()}</section>`, 'welcome-page');
}
function door(id){
 const t=T[id];
 if(!t)return home();
 return toolDoor({
  name:t.name, id, ...STARTS[id], diagram:diagramMarkup(id,0),
  idea:`#story/${id}`, project:`#make/${id}/context`, useCase:`#case/${id}`,
  caseLabel:id===6?'Show me the studio use case.':undefined,
  projectHint:id===1?'Paste your brief, review it in four stages, then define the problem.':'Bring your context. Work through the method with guidance.'
 });
}
